#!/usr/bin/env python3
# Optional Godmode Music Pack; no credential or business modules.
import sys
if sys.version_info < (3, 9):
    sys.exit('Music Pack needs Python 3.9 or newer.')
MUSIC_PACK_VERSION = '0.19.2'


# --- godmode_terminal.py ---
"""Small terminal prompts: an arrow-key menu, partly masked input with a live preview, plain ANSI color."""
import contextlib
import os
import re
import select
import shutil
import signal
import sys
import termios
import textwrap
import time
import tty
import unicodedata

TERM_MAX_INPUT = 1024 * 1024
TERM_STYLE = re.compile(r"\033\[[0-9;]*m")
TERM_PASTE = (b"\x1b[200~", b"\x1b[201~")
TERM_KEYS = {3: "cancel", 4: "cancel", 9: "tab", 10: "enter", 13: "enter", 8: "backspace", 127: "backspace",
             14: "down", 16: "up", 21: "clear"}
TERM_ARROWS = {"A": "up", "B": "down", "C": "right", "D": "left", "H": "home", "F": "end",
               "1~": "home", "7~": "home", "4~": "end", "8~": "end", "5~": "pageup", "6~": "pagedown"}


class Cancelled(Exception):
    """The user left a prompt without submitting its value."""


class Back(Cancelled):
    """Escape: leave this prompt for the previous menu, saving nothing."""


def plain_enabled():
    """Sequential prompts for screen readers and terminals without cursor controls."""
    return (os.environ.get("GODMODE_PLAIN", "").lower() not in ("", "0", "false", "no")
            or os.environ.get("TERM", "dumb") in ("", "dumb"))


plain_mode = plain_enabled


def color_enabled(stream=None):
    stream = sys.stdout if stream is None else stream
    return (stream.isatty() and not plain_enabled() and "NO_COLOR" not in os.environ
            and os.environ.get("CLICOLOR") != "0"
            and os.environ.get("TERM", "dumb") not in ("", "dumb"))


def style(text, role="accent"):
    # dim is faint (SGR 2), not bright black (SGR 90), which some themes draw in the background color.
    codes = {"title": "1", "heading": "1", "accent": "36", "link": "4;36", "secret": "1;36",
             "success": "32", "warning": "33", "error": "31", "dim": "2", "brand": "1;36", "risk": "1;33",
             "nfo": "1;35", "nfo_edge": "36", "diff_add": "32", "diff_remove": "31"}
    if not color_enabled() or role not in codes or not str(text):
        return str(text)
    return "\033[" + codes[role] + "m" + str(text) + "\033[0m"


def meter(points, total, width):
    """A progress bar of width cells for points out of total, never fuller than it is.

    Color draws a heavy line on a faint one, green when full. Without color, solid blocks
    on shaded ones keep the two parts apart; without Unicode, # on -.
    """
    filled = width * max(0, min(points, total)) // total if total else 0
    if not glyph("u", ""):
        return "#" * filled + "-" * (width - filled)
    if not color_enabled():
        return "\u2588" * filled + "\u2591" * (width - filled)
    return style("\u2501" * filled, "success" if points >= total else "accent") + style("\u2500" * (width - filled), "dim")


def glyph(fancy, plain):
    """Use a Unicode symbol only when the terminal can show it (the Linux console font cannot)."""
    unicode = "utf" in (getattr(sys.stdout, "encoding", "") or "").lower() and os.environ.get("TERM") != "linux"
    return fancy if unicode and not plain_enabled() else plain


def mask(value, reveal=True):
    """Hide a value, keeping a few characters at each end of a pasted value to recognize it.

    A pasted value shows at most three characters at each end, never more than a quarter
    of it: 24+ characters show 3+3, 16-23 show 2+2, 8-15 show 1+1, shorter ones only dots.
    Spaces, control and non-ASCII characters at the ends stay hidden too. A typed or edited
    value (reveal=False) shows one dot per character, like an ordinary password field.
    """
    if not value:
        return ""
    dot = glyph("•", "*")
    if not reveal:
        return dot * min(len(value), 24)
    visible = min(3, len(value) // 8)
    if not visible:
        return dot * 5

    def edge(text):
        return "".join(c if " " < c < "\x7f" else dot for c in text)
    return edge(value[:visible]) + dot * 5 + edge(value[-visible:])


def cells(text):
    """Terminal columns a string occupies, ignoring color codes."""
    width = 0
    for char in TERM_STYLE.sub("", text):
        if unicodedata.combining(char):
            continue
        width += 2 if unicodedata.east_asian_width(char) in ("W", "F") else 1
    return width


def drawn_height(rows, width):
    """Screen rows these rows take once the terminal wraps anything wider than width."""
    return sum(max(1, -(-cells(row) // width)) for row in rows)


def fit(text, columns):
    """Split plain text into rows that stay clear of the terminal's last column."""
    size, rows, row = max(1, columns - 1), [], ""
    for char in text:
        if row and cells(row + char) > size:
            rows.append(row)
            row = ""
        row += char
    return rows + [row]


def columns():
    """Terminal width. Some terminals report 0 columns; treat that as unknown."""
    size = shutil.get_terminal_size((80, 24))
    return size.columns if size.columns > 0 else 80


def plain_columns():
    """Static output wraps in scrollback; it does not need to fit the viewport."""
    return max(40, columns())


def screen_rows():
    size = shutil.get_terminal_size((80, 24))
    return size.lines if size.lines > 0 else 24


class Prompt:
    """What a text prompt draws. The last rendered row is the input line, where the cursor rests."""
    pastes = True  # False for a field shown as typed, so a secret pasted there by mistake never appears.
    pasted = False  # read_secret sets this while the field holds any pasted text.
    reviewing = False  # Static mode has displayed the value and awaits confirmation.

    def __init__(self, label, hidden=True):
        self.label, self.hidden = label, hidden

    def render(self, value, width, reveal=True):
        shown = mask(value, reveal) if self.hidden else value
        rows = textwrap.wrap(self.label, max(1, width - 3)) or [""]
        entry = "  " + glyph("› ", "> ")
        return ["  " + row for row in rows[:-1]] + ["  " + style(rows[-1], "dim"),
                                                     entry + fit(shown, width - cells(entry))[-1]]

    def enter(self, value):
        """What Enter does: True submits, False refuses, a list of rows is printed above the prompt."""
        return True

    def toggle(self):
        """Tab may disclose detail without changing the field or submitting it."""
        return False

    def final(self, value, width, reveal, submitted):
        """Rows left on screen once the prompt ends."""
        return self.render(value, width, reveal)


def _draw(rows, previous):
    """Redraw the prompt region in place and return the width of each row drawn.

    `previous` holds the widths last drawn, so the region's height is recomputed at the
    current width even after the terminal was resized and reflowed its lines.
    """
    width, height = columns(), screen_rows()

    def tall(widths):
        return sum(max(1, -(-w // width)) for w in widths)
    widths = [cells(row) for row in rows]
    while len(rows) > 1 and tall(widths) > height - 1:
        rows, widths = rows[1:], widths[1:]  # Last resort; prompts condense themselves first.
    # Assumes the terminal reflowed earlier rows after a resize, as most current ones do.
    up = tall(previous) - 1 if previous else 0
    sys.stdout.write("\r" + ("\033[%dA" % up if up > 0 else "") + "\033[J" + "\r\n".join(rows))
    sys.stdout.flush()
    return widths


@contextlib.contextmanager
def quiet():
    """Keep the terminal from echoing between prompts, for a whole interactive session.

    Each prompt reads in raw mode, but between two prompts the terminal would be back
    to normal and would print a paste that lands in that moment. With echo off for the
    session, such input is dropped unseen. The terminal is restored at the end.
    """
    if not sys.stdin.isatty():
        yield
        return
    fd = sys.stdin.fileno()
    saved = termios.tcgetattr(fd)
    silent = termios.tcgetattr(fd)
    silent[3] &= ~termios.ECHO

    def interrupted(_number, _frame):
        raise Cancelled()
    handlers = {number: signal.signal(number, interrupted) for number in (signal.SIGTERM, signal.SIGHUP)}
    try:
        termios.tcsetattr(fd, termios.TCSADRAIN, silent)
        yield
    finally:
        termios.tcsetattr(fd, termios.TCSAFLUSH, saved)
        for number, previous in handlers.items():
            signal.signal(number, previous)


def _key_name(code):
    """Name the key for the body of an escape sequence, such as "A", "1;5B" or "5~"."""
    if code.endswith("~"):
        return TERM_ARROWS.get(code[:-1].split(";")[0] + "~")
    return TERM_ARROWS.get(code[-1:])


class _Keyboard:
    """Raw terminal input for one prompt, restored on every way out.

    read() waits for the next event:
      ("text", bytes)    typed characters
      ("paste", bytes)   one whole bracketed paste, never interpreted as keys
      ("reject", None)   a paste that was too large or held a NUL byte, once all of it has arrived
      ("key", name)      enter, esc, tab, backspace, clear, up, down, left, right, home, end, pageup, pagedown
      ("resize", None)   the window changed size
    Ctrl-C, Ctrl-D and termination signals raise Cancelled.
    """

    def __enter__(self):
        if not sys.stdin.isatty() or not sys.stdout.isatty():
            raise ValueError("This prompt needs a terminal.")
        self.fd = sys.stdin.fileno()
        self.saved = termios.tcgetattr(self.fd)
        self.events, self.pending, self.paste, self.rejected = [], bytearray(), None, False
        self.handlers, self.previous_wake = {}, None
        # A resize writes to this pipe, so select() wakes up and the prompt redraws at once.
        self.wake, self.wake_write = os.pipe()
        os.set_blocking(self.wake, False)
        os.set_blocking(self.wake_write, False)

        def interrupted(_number, _frame):
            raise Cancelled()
        try:
            for number in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
                self.handlers[number] = signal.signal(number, interrupted)
            self.handlers[signal.SIGWINCH] = signal.signal(signal.SIGWINCH, lambda *_: None)
            self.previous_wake = signal.set_wakeup_fd(self.wake_write)
            tty.setraw(self.fd)
            sys.stdout.write("\033[?2004h")
        except BaseException:
            self.__exit__()
            raise
        return self

    def __exit__(self, *_):
        # Flush unread input so a cancelled paste cannot become a shell command.
        termios.tcsetattr(self.fd, termios.TCSAFLUSH, self.saved)
        if self.previous_wake is not None:
            signal.set_wakeup_fd(self.previous_wake)
        for number, previous in self.handlers.items():
            signal.signal(number, previous)
        os.close(self.wake)
        os.close(self.wake_write)
        sys.stdout.write("\033[?2004l" + ("" if plain_enabled() else "\033[?25h"))
        sys.stdout.flush()

    def read(self):
        while not self.events:
            # An isolated Escape is the Escape key; a fragmented sequence gets time to arrive.
            waiting = self.pending.startswith(b"\x1b") and self.paste is None
            ready = select.select([self.fd, self.wake], [], [], 0.08 if waiting else None)[0]
            if not ready:
                alone = self.pending == b"\x1b"
                self.pending.clear()  # A stalled fragment of a longer sequence is dropped, not a key.
                if alone:
                    return ("key", "esc")
                continue
            if self.wake in ready:
                with contextlib.suppress(BlockingIOError):
                    while os.read(self.wake, 512):
                        pass
                return ("resize", None)
            chunk = os.read(self.fd, 4096)
            if not chunk:
                raise Cancelled()
            self.pending.extend(chunk)
            self._parse()
        return self.events.pop(0)

    def poll(self, timeout=0):
        """Return one event or None without waiting for a complete paste.

        Animations use the same hidden, bounded paste parser as ordinary prompts.
        Partial pastes stay buffered; Escape alone needs the same 80 ms grace.
        """
        deadline = time.monotonic() + max(0, timeout)
        for _ in range(64):  # Drain at most 256 KiB before letting an animation draw.
            if self.events:
                return self.events.pop(0)
            waiting = self.pending.startswith(b"\x1b") and self.paste is None
            now = time.monotonic()
            since = getattr(self, "poll_escape_since", None)
            if waiting:
                if since is None:
                    self.poll_escape_since = since = now
                if now - since >= 0.08:
                    alone = self.pending == b"\x1b"
                    self.pending.clear()
                    self.poll_escape_since = None
                    return ("key", "esc") if alone else None
            else:
                self.poll_escape_since = None
            delay = max(0, deadline - now)
            if waiting:
                delay = min(delay, max(0, 0.08 - (now - since)))
            ready = select.select([self.fd, self.wake], [], [], delay)[0]
            if not ready:
                if waiting and time.monotonic() - since >= 0.08:
                    continue
                return None
            if self.wake in ready:
                with contextlib.suppress(BlockingIOError):
                    while os.read(self.wake, 512):
                        pass
                return ("resize", None)
            chunk = os.read(self.fd, 4096)
            if not chunk:
                raise Cancelled()
            self.pending.extend(chunk)
            self._parse()
            if not self.pending.startswith(b"\x1b") or self.paste is not None:
                self.poll_escape_since = None
        return self.events.pop(0) if self.events else None

    def _parse(self):
        """Turn complete input into events; leave an unfinished sequence for the next read."""
        pending, start, end = self.pending, TERM_PASTE[0], TERM_PASTE[1]
        while pending:
            if self.paste is not None:
                found = pending.find(end)
                # Hold back a possibly split end marker; pasted bytes are data, never keys.
                take = found if found >= 0 else max(0, len(pending) - len(end))
                if not self.rejected:
                    self.paste.extend(pending[:take])
                del pending[:take]
                if len(self.paste) > TERM_MAX_INPUT or b"\0" in self.paste:
                    # Keep reading to the end of the paste before refusing it. Leaving now would
                    # let the terminal deliver the rest of it to the shell as commands.
                    self.rejected = True
                    self.paste[:] = b""
                if found < 0:
                    return
                del pending[:len(end)]
                self.events.append(("reject", None) if self.rejected else ("paste", bytes(self.paste)))
                self.paste, self.rejected = None, False
            elif pending[0] != 27:
                char = pending.pop(0)
                if TERM_KEYS.get(char) == "cancel":
                    raise Cancelled()
                if char in TERM_KEYS:
                    self.events.append(("key", TERM_KEYS[char]))
                elif char >= 32:
                    self.events.append(("text", bytes([char])))
            elif pending.startswith(start):
                del pending[:len(start)]
                self.paste = bytearray()
            elif len(pending) < 2 or start.startswith(bytes(pending)):
                return  # Only an Escape so far; read() decides after a short wait.
            elif pending[1] == 27:
                del pending[:1]  # Alt+arrow arrives as Escape, then the arrow's own sequence.
            elif pending[1] not in b"[O":
                del pending[:2]  # Ignore an Alt-key sequence.
            elif pending[1:3] == b"[[":
                if len(pending) < 4:
                    return
                del pending[:4]  # A Linux console function key.
            else:
                last = next((i for i in range(2, len(pending)) if 0x40 <= pending[i] <= 0x7e), None)
                if last is None and len(pending) < 32:
                    return
                last = len(pending) - 1 if last is None else last
                name = _key_name(bytes(pending[2:last + 1]).decode("ascii", "ignore"))
                del pending[:last + 1]
                if name:
                    self.events.append(("key", name))


def read_secret(prompt):
    """Return a hidden value. Pasting never submits; only Enter does."""
    prompt = prompt if isinstance(prompt, Prompt) else Prompt(prompt)
    if plain_enabled():
        return _plain_secret(prompt)
    value, drawn, submitted = bytearray(), [], False
    # Ends are shown only for a value pasted into an empty field. Typing or deleting
    # would otherwise reveal every character as it passes through the visible end.
    reveal = True

    def text():
        return value.decode("utf-8", "ignore")

    def clear():
        value[:] = b"\0" * len(value)
        value.clear()

    def add(data):
        if len(value) + len(data) > TERM_MAX_INPUT:
            raise ValueError("Input is too large; nothing saved.")
        value.extend(data)

    with _Keyboard() as keyboard:
        try:
            while True:
                drawn = _draw(prompt.render(text(), columns(), reveal), drawn)
                kind, key = keyboard.read()
                if kind == "reject":
                    raise ValueError("Input is too large or contains a NUL byte; nothing saved.")
                elif kind == "paste" and not prompt.pastes:
                    sys.stdout.write("\a")
                elif kind == "paste":
                    if reveal:
                        clear()  # Pasting again replaces a pasted value instead of doubling it.
                    add(key)
                    prompt.pasted = True
                elif kind == "text":
                    add(key)
                    reveal = False
                elif key == "backspace" and value:
                    start = len(value) - 1
                    while start > 0 and (value[start] & 0xc0) == 0x80:
                        start -= 1
                    del value[start:]
                    reveal = False
                elif key == "clear":
                    clear()
                elif kind == "key" and key == "tab":
                    prompt.toggle()
                elif key == "esc":
                    raise Back()
                elif key == "enter":
                    try:
                        answer = value.decode("utf-8")
                    except UnicodeDecodeError:
                        raise ValueError("Input is not valid UTF-8; nothing saved.") from None
                    outcome = prompt.enter(answer)
                    if outcome is True:
                        submitted = True
                        return answer
                    if outcome is False:
                        sys.stdout.write("\a")
                    else:
                        _draw([], drawn)
                        sys.stdout.write("".join(row + "\r\n" for row in outcome))
                        drawn = []
                if not value:
                    reveal, prompt.pasted = True, False
        finally:
            left = prompt.final(text(), columns(), reveal, submitted)
            _draw(left, drawn)
            clear()
            sys.stdout.write("\r\n" if left else "")


def _plain_rows(rows):
    """Append static rows without terminal drawing or color sequences."""
    sys.stdout.write("\r\n".join(TERM_STYLE.sub("", str(row)) for row in rows) + "\r\n")
    sys.stdout.flush()


def _plain_secret(prompt):
    """Hidden input followed by a static review; a separate Enter submits it.

    Bracketed paste remains enabled, so pasted newlines never act as Enter keys.
    This mode emits no cursor movement, erase codes, color, or per-key redraws.
    """
    value, submitted, reviewed, paste_only = bytearray(), False, False, True

    def text():
        return value.decode("utf-8", "ignore")

    with _Keyboard() as keyboard:
        try:
            _plain_rows(prompt.render("", plain_columns(), False))
            _plain_rows(["  Input hidden. Enter reviews."])
            while True:
                kind, key = keyboard.read()
                if kind == "reject":
                    raise ValueError("Input is too large or contains a NUL byte; nothing saved.")
                if kind == "paste" and not prompt.pastes:
                    _plain_rows(["  Paste ignored. Type the name."])
                    continue
                if kind in ("text", "paste"):
                    if kind == "paste" and paste_only:
                        value[:] = b"\0" * len(value)
                        value.clear()
                    if len(value) + len(key) > TERM_MAX_INPUT:
                        raise ValueError("Input is too large; nothing saved.")
                    value.extend(key)
                    prompt.pasted = kind == "paste" or prompt.pasted
                    reviewed = False
                    if kind == "text":
                        paste_only = False
                elif kind == "key" and key == "backspace":
                    if value:
                        start = len(value) - 1
                        while start > 0 and (value[start] & 0xc0) == 0x80:
                            start -= 1
                        del value[start:]
                    reviewed = False
                    paste_only = False
                elif kind == "key" and key == "clear":
                    value[:] = b"\0" * len(value)
                    value.clear()
                    reviewed = False
                elif kind == "key" and key == "tab":
                    prompt.toggle()
                    prompt.reviewing = reviewed
                    _plain_rows(prompt.render(text(), plain_columns(), False))
                elif kind == "key" and key == "esc":
                    raise Back()
                elif kind == "key" and key == "enter":
                    try:
                        answer = value.decode("utf-8")
                    except UnicodeDecodeError:
                        raise ValueError("Input is not valid UTF-8; nothing saved.") from None
                    if answer and not reviewed:
                        prompt.reviewing = True
                        _plain_rows(prompt.render(answer, plain_columns(), False))
                        if not hasattr(prompt, "hint"):
                            _plain_rows(["  Enter confirms. Ctrl-U clears. Esc back."])
                        reviewed = True
                        continue
                    outcome = prompt.enter(answer)
                    if outcome is True:
                        submitted = True
                        return answer
                    if outcome is False:
                        prompt.reviewing = False
                        _plain_rows(prompt.render(answer, plain_columns(), False))
                    else:
                        _plain_rows(outcome)
                        prompt.reviewing = False
                        _plain_rows(prompt.render(answer, plain_columns(), False))
                    reviewed = False
                if not value:
                    prompt.pasted = False
                    paste_only = True
                prompt.reviewing = reviewed
        finally:
            prompt.final(text(), plain_columns(), False, submitted)
            value[:] = b"\0" * len(value)
            value.clear()
            sys.stdout.write("\r\n")


def _plain_choice(label, choices, keyboard=None):
    options = {str(choice).casefold(): str(choice) for choice in choices}
    value = bytearray()
    with (_Keyboard() if keyboard is None else contextlib.nullcontext(keyboard)) as keyboard:
        _plain_rows([label])
        while True:
            kind, key = keyboard.read()
            if kind == "text":
                # Input stays hidden. Validate the whole choice on Enter: dropping
                # an invalid digit could turn "12" into "1", or "9" into a default.
                if len(value) + len(key) > TERM_MAX_INPUT:
                    raise ValueError("Input is too large; no choice selected.")
                value.extend(key)
            elif kind == "key" and key == "backspace":
                if value:
                    start = len(value) - 1
                    while start > 0 and (value[start] & 0xc0) == 0x80:
                        start -= 1
                    del value[start:]
            elif kind == "key" and key == "clear":
                value.clear()
            elif kind == "key" and key == "esc":
                raise Back()
            elif kind == "key" and key == "enter":
                try:
                    answer = value.decode("utf-8").casefold()
                except UnicodeDecodeError:
                    answer = None
                if answer in options:
                    _plain_rows([options[answer]])
                    return options[answer]
                _plain_rows(["  Invalid choice. Ctrl-U clears. Type a listed choice, then Enter."])


def read_choice(label, choices):
    """Return a listed choice typed in full; never echo an unexpected pasted value."""
    if plain_enabled():
        return _plain_choice(label, choices)
    options = {str(choice).casefold(): str(choice) for choice in choices}
    prompt, value, drawn = Prompt(label, hidden=False), bytearray(), []

    def fits(data, pasted):
        try:
            candidate = (value + data).decode("utf-8").casefold()
        except UnicodeDecodeError:  # The first bytes of a character still being typed.
            return not pasted and any(option.encode("utf-8").startswith(value + data) for option in options)
        # Pasting a credential into a confirmation must not put it in scrollback.
        return candidate in options if pasted else any(option.startswith(candidate) for option in options)

    with _Keyboard() as keyboard:
        try:
            while True:
                drawn = _draw(prompt.render(value.decode("utf-8", "ignore"), columns()), drawn)
                kind, key = keyboard.read()
                if kind in ("text", "paste"):
                    if fits(key, kind == "paste"):
                        value.extend(key)
                elif key == "backspace" and value:
                    del value[-1:]
                    while value and (value[-1] & 0xc0) == 0x80:
                        del value[-1:]
                elif key == "clear":
                    value.clear()
                elif key == "esc":
                    raise Back()
                elif key == "enter":
                    answer = value.decode("utf-8", "ignore").casefold()
                    if answer in options:
                        return options[answer]
                    sys.stdout.write("\a")
        finally:
            sys.stdout.write("\r\n")


def read_page(render):
    """An Enter-paced page. Text and pastes are ignored; Esc goes back."""
    if plain_enabled():
        with _Keyboard() as keyboard:
            rows, ready = render(plain_columns(), 1000000)
            _plain_rows(rows)
            while True:
                kind, key = keyboard.read()
                if kind == "key" and key == "esc":
                    raise Back()
                if kind == "key" and key == "enter" and ready:
                    return
                if kind == "resize" and not ready:
                    rows, ready = render(plain_columns(), 1000000)
                    _plain_rows(rows)
    drawn = []
    with _Keyboard() as keyboard:
        try:
            sys.stdout.write("\033[?25l")
            while True:
                rows, ready = render(columns(), screen_rows())
                drawn = _draw(rows, drawn)
                kind, key = keyboard.read()
                if kind == "key" and key == "esc":
                    raise Back()
                if kind == "key" and key == "enter" and ready:
                    return
        finally:
            _draw([], drawn)


def read_menu(items, start=0, hint="", title="", gap=False, header=None, status_width=0, abouts=False,
              searchable=False, header_required=False, row_spacing=0):
    """Choose a row with the arrow keys and return its index; Escape raises Back.

    items are (name, status, about) rows; None leaves a gap that cannot be chosen.
    A status is text or (text, role) and shows on every row in one column. The
    description shows on the row the pointer is on, or faintly on every row with
    abouts. Typing letters jumps to the first name that starts with them, and the same
    letter again moves to the next such name. searchable adds a slash filter; pastes
    never enter a search. Tab opens the full selected row when its text is clipped.
    header(width) returns rows above the title. A required header blocks selection
    until it fits; optional headers may collapse. Plain mode prints every row and
    accepts a number. Visual menus erase their own region when they end.
    """
    choices = [index for index, item in enumerate(items) if item]
    if not choices:
        raise ValueError("This menu has no choices.")
    if plain_enabled():
        return _plain_menu(items, start, title, header)
    at = start if start in choices else choices[0]
    typed, drawn = "", []
    filtering, query, blocked, details, detail_offset = False, "", False, False, 0
    pointer, more = glyph("❯ ", "> "), glyph("  ⋮", "  :")
    dot = glyph(" · ", " | ")

    def status(item):
        mark = item[1]
        return (mark, None) if isinstance(mark, str) else (mark[0], mark[1])
    # Columns are sized by the rows that have something to show beside their name.
    names = max([cells(items[i][0]) for i in choices if status(items[i])[0] or items[i][2] or status_width] or [0]) + 2
    marks = max([status_width] + [cells(status(items[index])[0]) for index in choices])
    marks += 2 if marks else 0

    def starting(letters):
        return [index for index in choices if items[index][0].casefold().startswith(letters)]

    def matches():
        return [i for i in choices if query.casefold() in (items[i][0] + " " + items[i][2]).casefold()] if query else choices

    def short(text, size):
        text = TERM_STYLE.sub("", text)
        if cells(text) <= size:
            return text
        end = glyph("…", "...")
        return fit(text, max(2, size - cells(end) + 1))[0] + end if size > cells(end) else ""

    def heading(width):
        if not title:
            return []
        rows = []
        for row in textwrap.wrap(title, max(1, width - 3), break_on_hyphens=False):
            lead, sep, rest = row.partition(dot) if not rows else ("", "", row)
            rows.append("  " + (style(lead, "title") + style(sep + rest, "dim") if lead else style(rest, "dim")))
        return rows

    def render():
        nonlocal blocked, detail_offset
        width = columns()
        if details:
            name, about = items[at][0], items[at][2]
            mark = TERM_STYLE.sub("", status(items[at])[0])
            full = []
            for text in (name, mark, about):
                if text:
                    full += ["  " + row for row in textwrap.wrap(TERM_STYLE.sub("", text), max(1, width - 3))]
            room = max(1, screen_rows() - 4)
            detail_offset = min(detail_offset, max(0, len(full) - room))
            return full[detail_offset:detail_offset + room] + ["", "  " + short("Up/Down scroll | Tab back", width - 3)]
        top_rows = list(header(width)) if header else []
        titled = heading(width)
        selected_name, selected_about = items[at][0], items[at][2]
        selected_mark = status(items[at])[0]
        available = max(1, width - 3)
        mark_width = min(marks, max(0, available // 2))
        name_width = min(names, max(1, available - mark_width)) if selected_mark or selected_about else available
        name_limit = max(1, name_width - 2) if selected_mark or selected_about else available
        cut = (cells(selected_name) > name_limit or cells(selected_mark) > max(0, mark_width - 2)
               or cells(selected_about) > max(0, available - name_width - mark_width))
        help_text = hint + ("  / search" if searchable else "") + ("  Tab details" if cut else "")
        below = [""] + ["  " + style(row, "dim") for row in textwrap.wrap(help_text, max(1, width - 3))] if help_text else []
        above = ([""] if gap else []) + top_rows + ([""] if top_rows else []) + titled + ([""] if titled else [])
        blocked = header_required and drawn_height(above + below, width) + min(3, len(items)) > screen_rows() - 1
        if blocked:
            return ["  " + row for row in textwrap.wrap("Enlarge the terminal to review all changes. Esc back.", max(1, width - 3))]
        if top_rows and not header_required and len(above) + min(5, len(items)) + len(below) > screen_rows() - 1:
            above = ([""] if gap else []) + titled + ([""] if titled else [])  # A short window drops the header first.
        if filtering:
            above += ["  / " + (short(query, max(1, width - 5)) if matches() else "No matches"), ""]
        room = max(3, screen_rows() - 1 - len(above) - len(below))
        indices = matches() if filtering else list(range(len(items)))
        if not indices:
            return above + ["  No matches"] + below
        position = indices.index(at) if at in indices else 0
        top = 0 if len(indices) <= room else min(max(0, position - room // 2), len(indices) - room)
        rows = []
        for slot in range(top, min(len(indices), top + room)):
            index = indices[slot]
            if (slot == top and top > 0) or (slot == top + room - 1 and slot < len(indices) - 1):
                rows.append(more)  # The list is taller than the window and continues.
            elif not items[index]:
                rows.append("")
            else:
                name, about = items[index][0], items[index][2]
                mark, role = status(items[index])
                focus = index == at
                note = about if (focus or abouts) else ""
                available = max(1, width - 3)
                mark_width = min(marks, max(0, available // 2))
                name_width = min(names, max(1, available - mark_width)) if mark or note else available
                name_limit = max(1, name_width - 2) if mark or note else available
                name = short(name, name_limit) if cells(name) > name_limit else name
                mark = short(mark, max(0, mark_width - 2)) if cells(mark) > max(0, mark_width - 2) else mark
                room_left = available - name_width - mark_width
                if note and cells(note) > room_left:
                    note = (fit(note, room_left)[0].rstrip() + glyph("…", "")
                            if room_left > 4 and not note.startswith("godmode ") else "")
                row = style(name, "title") if focus else name
                if mark or note:
                    row += " " * max(0, name_width - cells(name)) + (style(mark, role) if role else mark)
                if note:
                    row += " " * max(0, mark_width - cells(mark)) + (note if focus else style(note, "dim"))
                rows.append((style(pointer, "accent") if focus else "  ") + row)
        if row_spacing and drawn_height(above + rows + below, width) + row_spacing * (len(rows) - 1) <= screen_rows() - 1:
            rows = [part for index, row in enumerate(rows)
                    for part in (([""] * row_spacing if index else []) + [row])]
        return above + rows + below

    with _Keyboard() as keyboard:
        try:
            sys.stdout.write("\033[?25l")
            while True:
                drawn = _draw(render(), drawn)
                kind, key = keyboard.read()
                if details:
                    if kind == "key" and key in ("tab", "esc"):
                        details, detail_offset = False, 0
                    elif kind == "key" and key in ("up", "pageup"):
                        detail_offset = max(0, detail_offset - (5 if key == "pageup" else 1))
                    elif kind == "key" and key in ("down", "pagedown"):
                        detail_offset += 5 if key == "pagedown" else 1
                    continue
                if blocked:
                    if kind == "key" and key == "esc":
                        raise Back()
                    continue
                if kind == "key" and key == "tab":
                    details, detail_offset = True, 0
                    continue
                if searchable and kind == "text" and key == b"/" and not filtering:
                    filtering, query, typed = True, "", ""
                    continue
                if filtering:
                    if kind == "text" and len(query) < 64:
                        letter = key.decode("ascii", "ignore")
                        if letter and letter.isprintable():
                            query += letter
                    elif kind == "key" and key == "backspace":
                        query = query[:-1]
                    elif kind == "key" and key == "clear":
                        query = ""
                    elif kind == "key" and key == "esc":
                        filtering, query = False, ""
                        continue
                    found = matches()
                    if found and at not in found:
                        at = found[0]
                    if kind != "key" or key not in ("up", "down", "pageup", "pagedown", "home", "end", "enter"):
                        continue
                    if not found:
                        continue
                if kind == "text":
                    letter = key.decode("utf-8", "ignore").casefold()
                    if not letter:
                        continue  # Part of a character outside ASCII.
                    found = starting(typed + letter)
                    if found:
                        typed += letter
                    elif typed and set(typed) == {letter}:
                        found = starting(letter)  # The same letter again: the next name with it.
                        found = [index for index in found if index > at] or found
                    else:
                        typed, found = letter, starting(letter)
                    at = found[0] if found else at
                    continue
                typed = ""
                active = matches() if filtering else choices
                step = {"up": -1, "down": 1, "pageup": -5, "pagedown": 5}.get(key) if kind == "key" else None
                if step in (-1, 1):
                    at = active[(active.index(at) + step) % len(active)]  # Wraps around.
                elif step:
                    at = active[min(max(0, active.index(at) + step), len(active) - 1)]
                elif key in ("home", "end"):
                    at = active[0 if key == "home" else -1]
                elif key == "enter":
                    return at
                elif key == "esc":
                    raise Back()
        finally:
            _draw([], drawn)


def _plain_menu(items, start, title, header):
    choices = [i for i, item in enumerate(items) if item]
    rows = list(header(plain_columns())) if header else []
    if title:
        rows += [title]
    for number, index in enumerate(choices, 1):
        name, mark, about = items[index]
        mark = mark if isinstance(mark, str) else mark[0]
        rows.append("%d. %s%s" % (number, name, ": " + TERM_STYLE.sub("", mark) if mark else ""))
        if about:
            rows.append("   " + about)
    default = choices.index(start) + 1 if start in choices else 1
    with _Keyboard() as keyboard:
        _plain_rows(rows)
        answer = _plain_choice("Number, then Enter (%d). Esc back." % default,
                               [""] + [str(i) for i in range(1, len(choices) + 1)], keyboard)
    return choices[int(answer or default) - 1]


def read_document(title, paragraphs):
    """Read local prose with scrolling. Enter or Esc returns; pasted input stays hidden."""
    def rows(width):
        result = ["  " + style(title, "title"), ""]
        for paragraph in paragraphs:
            result += ["  " + row for row in textwrap.wrap(paragraph, max(1, width - 4),
                       break_on_hyphens=False)] + [""]
        return result
    if plain_enabled():
        with _Keyboard() as keyboard:
            _plain_rows(rows(plain_columns()) + ["Enter back."])
            while True:
                kind, key = keyboard.read()
                if kind == "key" and key in ("esc", "enter"):
                    return
    offset, drawn = 0, []
    with _Keyboard() as keyboard:
        try:
            sys.stdout.write("\033[?25l")
            while True:
                width, height = columns(), screen_rows()
                content, room = rows(width), max(1, height - 4)
                offset = min(offset, max(0, len(content) - room))
                hint = "Up/Down scroll | Enter back" if len(content) > room else "Enter back"
                footer = ["  " + style(row, "dim") for row in fit(hint, max(2, width - 2))]
                drawn = _draw(content[offset:offset + room] + [""] + footer, drawn)
                kind, key = keyboard.read()
                if kind == "key" and key in ("esc", "enter"):
                    return
                if kind == "key" and key in ("up", "pageup", "home"):
                    offset = 0 if key == "home" else max(0, offset - (room if key == "pageup" else 1))
                if kind == "key" and key in ("down", "pagedown", "end"):
                    offset = len(content) if key == "end" else offset + (room if key == "pagedown" else 1)
        finally:
            _draw([], drawn)


def motion_enabled():
    return (color_enabled() and os.environ.get("GODMODE_NO_MOTION", "").lower() in ("", "0", "false", "no"))


def animate_entrance(rows):
    """A brief logo reveal, only in a color terminal. No work or progress is implied."""
    if not motion_enabled() or not sys.stdin.isatty():
        return
    if drawn_height(rows, columns()) >= screen_rows() - 2:
        return
    drawn = []
    with _Keyboard() as keyboard:
        try:
            sys.stdout.write("\033[?25l")
            for count in range(1, len(rows) + 1):
                drawn = _draw(rows[:count], drawn)
                # Any input ends the reveal; it cannot submit the next screen.
                if select.select([keyboard.fd, keyboard.wake], [], [], 0.025)[0]:
                    return
        finally:
            _draw([], drawn)


# --- godmode_music.py ---
"""Optional local Darunia adapter. No network, downloaded code, catalog, or music assets.

Remove this file and its command/build hooks to remove music. Nothing imports
the key store. The optional Music Pack owns its synth runtime and assets.
"""
import argparse
import array
import contextlib
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import select
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
import wave

MUSIC_SOURCE = "https://github.com/lofimichael/darunias-cli"
MUSIC_LIMIT = 700 * 1024 * 1024
MUSIC_CONFIG_LIMIT = 65536


def _music_root(home=None):
    selected = home or os.environ.get("GODMODE_HOME") or str(Path.home() / ".godmode")
    return Path(os.path.abspath(os.path.expanduser(str(selected)))) / "state" / "music"


def _music_text(value):
    # File names and upstream metadata cannot write terminal controls.
    return "".join(c for c in str(value) if c.isprintable())


def _music_directory(path, create=False):
    for directory in reversed((path,) + tuple(path.parents)):
        if create and not os.path.lexists(directory):
            directory.mkdir(mode=0o700)
        if os.path.lexists(directory) and not stat.S_ISDIR(directory.lstat().st_mode):
            raise ValueError("Music paths must not contain symlinks.")
    if path.exists():
        info = path.stat()
        if info.st_uid != os.geteuid() or info.st_mode & 0o022:
            raise ValueError("Music files must be yours and not writable by other users.")


def _music_bytes(path, limit=MUSIC_CONFIG_LIMIT):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(fd, "rb") as stream:
        info = os.fstat(stream.fileno())
        if (not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid()
                or info.st_nlink != 1 or info.st_mode & 0o022 or info.st_size > limit):
            raise ValueError("Unsafe music file: " + _music_text(path.name))
        return stream.read(limit + 1)


def _music_sha(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for data in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(data)
    return digest.hexdigest()


@contextlib.contextmanager
def _music_lock(root):
    _music_directory(root, True)
    path = root / ".lock"
    fd = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW | os.O_NONBLOCK, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid() or info.st_nlink != 1:
            raise ValueError("Unsafe music lock.")
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise ValueError("Music is running. Stop it before changing its cache.") from None
        yield
    finally:
        os.close(fd)


def _music_atomic(path, data, limit=MUSIC_CONFIG_LIMIT):
    if os.path.lexists(path):
        _music_bytes(path, limit)
    fd, name = tempfile.mkstemp(prefix=".config-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(name, path)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def _music_config(root, verify=True):
    _music_directory(root)
    try:
        data = json.loads(_music_bytes(root / "config.json"))
    except FileNotFoundError:
        raise ValueError("Music is not set up. Run godmode music setup --songs TRACK_FOLDER.") from None
    if (not isinstance(data, dict) or data.get("version") != 1
            or any(not isinstance(data.get(k), str) for k in ("backend", "songs", "sha256"))):
        raise ValueError("Invalid music config. Run godmode music setup --songs TRACK_FOLDER.")
    backend, songs = Path(data["backend"]), Path(data["songs"])
    if not backend.is_absolute() or not songs.is_absolute():
        raise ValueError("Music paths must be absolute.")
    _music_directory(backend)
    _music_directory(songs)
    if verify:
        if data.get("runtime") == "owned":
            music_runtime_validate(backend, data.get("runtime_manifest"))
        script = _music_bytes(backend / "synthesize.py", 1024 * 1024)
        if hashlib.sha256(script).hexdigest() != data["sha256"]:
            raise ValueError("Darunia's synth changed. Review it, then run godmode music init again.")
    return data


def music_available(home=None):
    try:
        _music_config(_music_root(home))
        return True
    except (OSError, ValueError, TypeError):
        return False


def _music_init(root, backend, songs):
    backend = Path(os.path.abspath(os.path.expanduser(str(backend))))
    songs = Path(os.path.abspath(os.path.expanduser(str(songs))))
    _music_directory(backend)
    _music_directory(songs)
    if not songs.is_dir():
        raise ValueError("The song folder does not exist.")
    script = _music_bytes(backend / "synthesize.py", 1024 * 1024)
    required = (backend / "tools/render_synth", backend / "tools/seq64/build/seq64_console",
                backend / "tools/florestan-subset.sf2", backend / "oot-instruments.json")
    if any(not p.is_file() for p in required) or not shutil.which("ffmpeg"):
        raise ValueError("Darunia's synthesis tools are missing. Follow " + MUSIC_SOURCE + "/blob/main/docs/SYNTHESIS.md")
    data = {"version": 1, "backend": str(backend), "songs": str(songs),
            "sha256": hashlib.sha256(script).hexdigest()}
    count = len(_music_songs(songs))
    with _music_lock(root):
        _music_atomic(root / "config.json", (json.dumps(data, indent=2) + "\n").encode())
    print("Darunia's CLI linked. " + str(count) + " local tracks.")


def _music_songs(base):
    """Only local regular files; never walk symlinked directories."""
    result = []
    for directory, dirs, files in os.walk(base, followlinks=False):
        dirs[:] = sorted(d for d in dirs if not Path(directory, d).is_symlink())
        for name in sorted(files):
            path = Path(directory, name)
            if path.suffix.lower() == ".ootrs" and not path.is_symlink() and path.is_file():
                result.append(path)
                if len(result) > 10000:
                    raise ValueError("Music folders can hold at most 10,000 tracks.")
    return sorted(result, key=lambda p: str(p.relative_to(base)).casefold())


def _music_select(base, query, menu=None):
    songs = _music_songs(base)
    if query:
        exact = [p for p in songs if str(p.relative_to(base)).casefold() == query.casefold()]
        songs = exact or [p for p in songs if query.casefold() in str(p.relative_to(base)).casefold()]
    if not songs:
        raise ValueError("No local tracks match. Run godmode music list.")
    if len(songs) == 1:
        return songs[0]
    if menu is not None and sys.stdin.isatty() and sys.stdout.isatty():
        items = [(_music_text(p.stem), "", _music_text(str(p.relative_to(base).parent))) for p in songs]
        items.append(("Back", "", ""))
        choice = menu(items, title="Music", hint="↑↓ choose  Enter play  Esc back", searchable=True)
        return None if choice is None or choice == len(songs) else songs[choice]
    raise ValueError(str(len(songs)) + " tracks match. Use the path shown by godmode music list.")


def _music_env():
    names = ("PATH", "HOME", "USER", "LOGNAME", "LANG", "TERM", "COLORTERM", "TMPDIR",
             "DISPLAY", "WAYLAND_DISPLAY", "XDG_RUNTIME_DIR", "DBUS_SESSION_BUS_ADDRESS", "PULSE_SERVER")
    return {key: os.environ[key] for key in names if key in os.environ}


def _music_animated():
    return (sys.stdout.isatty() and sys.stdin.isatty() and os.environ.get("TERM", "dumb") not in ("", "dumb")
            and os.environ.get("GODMODE_PLAIN", "").lower() in ("", "0", "false", "no")
            and os.environ.get("GODMODE_NO_MOTION", "").lower() in ("", "0", "false", "no"))


def _music_color(text, code):
    if (sys.stdout.isatty() and "NO_COLOR" not in os.environ and os.environ.get("CLICOLOR") != "0"
            and os.environ.get("TERM", "dumb") not in ("", "dumb")
            and os.environ.get("GODMODE_PLAIN", "").lower() in ("", "0", "false", "no")):
        return "\x1b[" + code + "m" + text + "\x1b[0m"
    return text


@contextlib.contextmanager
def _music_controls(interactive, terminal):
    keyboard_factory, _, cancelled = terminal
    if interactive:
        try:
            with keyboard_factory() as keyboard:
                if _music_animated():
                    sys.stdout.write("\x1b[?25l")
                    sys.stdout.flush()
                try:
                    yield keyboard
                finally:
                    # A paste can span multiple OS writes. Keep echo off until
                    # input has been quiet briefly, then _Keyboard flushes it.
                    deadline = time.monotonic() + 0.5
                    while time.monotonic() < deadline:
                        if not select.select([keyboard.fd], [], [], 0.08)[0]:
                            break
                        if not os.read(keyboard.fd, 4096):
                            break
        except cancelled:
            raise KeyboardInterrupt() from None
        return
    handlers = {}
    def stop(signum, frame):
        raise KeyboardInterrupt()
    try:
        for signum in (signal.SIGTERM, signal.SIGHUP):
            handlers[signum] = signal.signal(signum, stop)
        yield None
    finally:
        for signum, handler in handlers.items():
            signal.signal(signum, handler)


def _music_quit(keyboard):
    if keyboard is not None:
        while True:
            event = keyboard.poll()
            if event is None:
                break
            kind, key = event
            if (kind == "text" and key in (b"q", b"Q")) or (kind == "key" and key == "esc"):
                return True
            # Pasted bytes, including q/newlines, are data and are always ignored.
    return False


def _music_end(child):
    # synthesize.py owns converter/renderer children; stop its whole process group.
    with contextlib.suppress(ProcessLookupError):
        os.killpg(child.pid, signal.SIGTERM)
    if child.poll() is None:
        try:
            child.wait(timeout=1)
        except subprocess.TimeoutExpired:
            pass
    # A converter can outlive its Python parent or ignore SIGTERM.
    with contextlib.suppress(ProcessLookupError):
        os.killpg(child.pid, signal.SIGKILL)
    child.wait()


def _music_run(command, frame=None, active=False, timeout=180, keyboard=None, cancel=None):
    with tempfile.TemporaryFile() as output:
        child = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=output, stderr=output,
                                 env=_music_env(), start_new_session=True)
        started = time.monotonic()
        try:
            while child.poll() is None:
                elapsed = time.monotonic() - started
                if cancel is not None and cancel.is_set():
                    raise InterruptedError("Music preparation cancelled.")
                if _music_quit(keyboard):
                    raise KeyboardInterrupt()
                if elapsed > timeout:
                    raise ValueError("Music timed out.")
                if os.fstat(output.fileno()).st_size > 1024 * 1024:
                    raise ValueError("The music program produced too much output.")
                if frame:
                    frame(elapsed)
                time.sleep(0.06)
            output.seek(0)
            log = output.read(65536).decode("utf-8", "replace")
            if child.returncode:
                raise ValueError("Darunia or the local audio player failed. Check godmode music status.")
            return log
        finally:
            _music_end(child)


def _music_validate_cache(cache):
    _music_directory(cache)
    if not cache.exists():
        return
    for directory, dirs, files in os.walk(cache, followlinks=False):
        for name in dirs:
            _music_directory(Path(directory, name))
        for name in files:
            path = Path(directory, name)
            info = path.lstat()
            if (not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid()
                    or info.st_nlink != 1 or info.st_mode & 0o022 or info.st_size > MUSIC_LIMIT):
                raise ValueError("Unsafe music cache. No files changed.")


def _music_print(text=""):
    sys.stdout.write(str(text).replace("\n", "\r\n") + "\r\n")
    sys.stdout.flush()


def _music_render(root, config, source, seconds, active=False, keyboard=None, draw=None, cancel=None, quiet=False):
    cache = root / "cache"
    _music_directory(cache, True)
    _music_validate_cache(cache)
    original_locks = set(cache.glob("*.lock"))
    # Darunia computes and verifies its own cache key from every input/tool/font.
    # An export gives us an exact path/receipt without parsing terminal output.
    with tempfile.TemporaryDirectory(prefix=".render-", dir=root) as work:
        export = Path(work) / "track.wav"
        command = [sys.executable, str(Path(config["backend"]) / "synthesize.py"), str(source),
                   "--seconds", str(seconds), "--cache-dir", str(cache), "--output", str(export)]
        spinner = ("|", "/", "-", "\\")
        drawn = []
        def frame(elapsed):
            nonlocal drawn
            width = shutil.get_terminal_size().columns
            label = "Synthesizing " + _music_text(source.stem)[:max(1, width - 32)] + " · q stop"
            if width < 30:
                label = "Rendering · q stop"[:max(1, width - 5)]
            drawn = draw(["  " + _music_color(spinner[int(elapsed * 8) % 4], "1;35") + " " + label], drawn)
        if not active and not quiet:
            _music_print("Synthesizing " + _music_text(source.stem))
        try:
            options = {"keyboard": keyboard}
            if cancel is not None:
                options["cancel"] = cancel
            log = _music_run(command, frame if active else None, active, **options)
        finally:
            # SIGTERM can bypass Darunia's finally block. Only remove empty locks
            # this invocation created, after all its child processes have stopped.
            for lock in set(cache.glob("*.lock")) - original_locks:
                if not lock.is_symlink() and lock.is_dir():
                    with contextlib.suppress(OSError):
                        lock.rmdir()
            if active:
                draw([], drawn)
        details = json.loads(_music_bytes(export.with_suffix(".synthesis.json"), 1024 * 1024))
        key = details.get("cache_key", "")
        if len(key) != 64 or any(c not in "0123456789abcdef" for c in key):
            raise ValueError("Darunia returned an invalid cache key.")
        cached = cache / key / "render.wav"
        _music_validate_cache(cache)
        if (not cached.is_file() or cached.stat().st_size > MUSIC_LIMIT
                or _music_sha(cached) != details.get("wav_sha256")):
            raise ValueError("Music cache checksum failed. Run godmode music clear.")
        return cached, details, "Cache hit:" in log


def _music_levels(audio, elapsed, count=24):
    """Log-spaced frequency bins from the PCM at the current playback position."""
    rate, channels = audio.getframerate(), audio.getnchannels()
    start = min(audio.getnframes(), max(0, int(elapsed * rate)))
    audio.setpos(start)
    values = array.array("h", audio.readframes(2048))
    if sys.byteorder != "little":
        values.byteswap()
    step = max(1, rate // 11025)
    mono = [sum(values[i:i + channels]) / (channels * 32768.0)
            for i in range(0, len(values) - channels + 1, channels * step)][:512]
    if not mono:
        return [0.0] * count
    size, sample_rate = len(mono), rate / step
    window = [x * (0.5 - 0.5 * math.cos(2 * math.pi * i / max(1, size - 1))) for i, x in enumerate(mono)]
    result = []
    for index in range(count):
        frequency = 70 * (min(4200, sample_rate * 0.45) / 70) ** (index / max(1, count - 1))
        coefficient = 2 * math.cos(2 * math.pi * frequency / sample_rate)
        first = second = 0.0
        for sample in window:
            current = sample + coefficient * first - second
            second, first = first, current
        power = max(0, first * first + second * second - coefficient * first * second)
        amplitude = math.sqrt(power) / size
        result.append(max(0.0, min(1.0, (20 * math.log10(amplitude + 1e-9) + 65) / 55)))
    return result


def _music_clock(seconds):
    return str(int(seconds) // 60) + ":" + str(int(seconds) % 60).zfill(2)


def music_visual_rows(levels, elapsed, duration, width=80, height=24):
    """Inspectable visualizer frame, also used by screenshot verification."""
    if width < 24 or height < 10:
        return [(_music_clock(elapsed) + " / " + _music_clock(duration))[:max(1, width - 1)],
                "q stop"[:max(1, width - 1)]]
    count = max(1, min(len(levels), (width - 6) // 3))
    tall = max(1, min(9, height - 9))
    colors = ("35", "35", "36", "36", "32", "33", "33", "31", "31")
    unicode = "utf" in (getattr(sys.stdout, "encoding", "") or "").lower() and os.environ.get("TERM") != "linux"
    block = "██" if unicode else "##"
    rows = []
    for row in range(tall, 0, -1):
        parts = [(_music_color(block, colors[min(8, row - 1)]) if level * tall >= row - 0.5 else "  ")
                 for level in levels[:count]]
        rows.append("  " + " ".join(parts))
    columns = max(1, min(66, width - 6))
    progress = int(columns * min(1, elapsed / duration)) if duration else 0
    rows += ["", "  " + _music_color("━" * progress if unicode else "#" * progress, "36")
             + _music_color("─" * (columns - progress) if unicode else "-" * (columns - progress), "2"),
             "  " + _music_clock(elapsed) + " / " + _music_clock(duration), "", "  q stop"]
    return rows


def _music_clear(root):
    _music_directory(root)
    if not root.exists():
        print("Music cache is empty.")
        return
    with _music_lock(root):
        cache = root / "cache"
        _music_validate_cache(cache)
        if cache.exists():
            shutil.rmtree(cache)
    print("Music cache cleared.")


def music_bridge(home=None):
    return music_session_bridge(home)


def music_serve(home=None):
    return music_session_serve(home)


def music_main(argv, home=None, menu=None, terminal=None):
    if argv and argv[0] in ("__bridge", "__serve"):
        return music_bridge(home) if argv[0] == "__bridge" else music_serve(home)
    if not argv:
        # Native terminals have their own browser. The Python/plain fallback is
        # deliberately static and bounded, even for libraries with many tracks.
        library = music_library(home)
        session = music_request({"action": "status"}, home)
        print("GODMODE BEATZ")
        if library["configured"]:
            print(str(len(library["tracks"])) + " local tracks linked · " + _music_text(session["state"]))
        else:
            print("No local library linked · " + _music_text(session["state"]))
            print("Setup: godmode music setup --songs TRACK_FOLDER")
        print("Find:  godmode music list QUERY")
        print("Play:  godmode music play NAME")
        print("Queue: godmode music queue")
        print("Stop:  godmode music stop")
        return 0
    if terminal is None:
        # Source-module use resolves core primitives here. Bundled entry points
        # inject these objects, so the removable adapter has no import hooks.
        import godmode_terminal as _music_core_terminal
        terminal = (_music_core_terminal._Keyboard, _music_core_terminal._draw, _music_core_terminal.Cancelled)
    parser = argparse.ArgumentParser(prog="godmode music", description="Local music through Darunia's CLI.")
    parser.add_argument("action", nargs="?", default="play", help="setup, play, list, queue, status, pause, resume, toggle, next, previous, seek, volume, repeat, shuffle, stop, init, clear, forget")
    parser.add_argument("query", nargs="?", default="", help="track name, or Darunia folder for init")
    parser.add_argument("--songs", type=Path, help="local .ootrs folder for setup or init")
    parser.add_argument("--seconds", type=float, default=180, help="audio length, from 1 to 3600 seconds")
    parser.add_argument("--render-only", action="store_true", help="cache the WAV without playing")
    parser.add_argument("extra", nargs="?", default="", help=argparse.SUPPRESS)
    parser.add_argument("--no-motion", action="store_true", help="disable animation in music views")
    parser.add_argument("--json", action="store_true", help="print session or library data as JSON")
    args = parser.parse_args(argv)
    if not math.isfinite(args.seconds) or not 1 <= args.seconds <= 3600:
        parser.error("--seconds must be from 1 to 3600")
    if args.songs is not None and args.action not in ("init", "setup"):
        parser.error("--songs belongs to music setup or init")
    if args.action in ("clear", "forget", "status", "pause", "resume", "toggle", "next", "previous", "stop") and args.query:
        parser.error("this command takes no track name")
    if args.extra and args.action != "queue":
        parser.error("too many command arguments")
    if args.action == "play" and not args.query:
        parser.error("play needs NAME. Find a track with godmode music list QUERY.")
    root = _music_root(home)
    if args.action == "setup":
        if args.query or not args.songs:
            parser.error("setup needs --songs TRACK_FOLDER")
        try:
            music_setup(home, args.songs)
        except KeyboardInterrupt:
            print("\nMusic setup cancelled. Existing configuration preserved.")
            return 130
        return 0
    if args.action == "status":
        session = music_request({"action": "status"}, home)
        if args.json:
            print(json.dumps(session, ensure_ascii=True, allow_nan=False))
            return 0
        library = music_library(home)
        print("Playback " + session["message"])
        print("Player   " + (shutil.which("mpv") or "mpv not installed"))
        if library["configured"]:
            print("Engine   " + _music_text(library["backend"]))
            print("Tracks   " + _music_text(library["songs"]))
            print("Cache    " + _music_text(root / "cache"))
        else:
            print(library.get("error", "Darunia is not linked."))
        if session["track"]:
            print("Current  " + _music_text(session["track"]["title"]))
            print("Position " + _music_clock(session["position"]) + " / " + _music_clock(session["duration"]))
        return 0
    if args.action in ("pause", "resume", "toggle", "next", "previous", "stop", "seek", "volume", "repeat", "shuffle"):
        request = {"action": args.action}
        if args.action in ("seek", "volume"):
            try:
                request["seconds" if args.action == "seek" else "value"] = float(args.query)
            except ValueError:
                parser.error(args.action + " needs a number")
        elif args.action == "repeat":
            request["value"] = args.query
        elif args.action == "shuffle":
            if args.query not in ("on", "off"):
                parser.error("shuffle needs on or off")
            request["value"] = args.query == "on"
        data = music_request(request, home)
        print(json.dumps(data, ensure_ascii=True, allow_nan=False) if args.json else data["message"])
        return 0
    if args.action == "queue":
        if args.query == "add":
            if not args.extra:
                parser.error("queue add needs NAME. Find a track with godmode music list QUERY.")
            config = _music_config(root)
            source = _music_select(Path(config["songs"]), args.extra, menu)
            if source is None:
                return 0
            data = music_request({"action": "enqueue", "ids": [str(source.relative_to(Path(config["songs"]))) ]}, home)
        elif args.query == "remove":
            try:
                index = int(args.extra) - 1
            except ValueError:
                parser.error("queue remove needs a 1-based index")
            data = music_request({"action": "remove", "index": index}, home)
        elif args.query == "clear":
            data = music_request({"action": "clear_queue"}, home)
        elif args.query:
            parser.error("queue accepts add NAME, remove INDEX, or clear")
        else:
            data = music_request({"action": "status"}, home)
        if args.json:
            print(json.dumps(data, ensure_ascii=True, allow_nan=False))
            return 0
        for index, track in enumerate(data["queue"]):
            print(("▶ " if index == data["index"] else "  ") + str(index + 1) + "  " + _music_text(track["id"]))
        if not data["queue"]:
            print("Queue empty.")
        return 0
    if args.action == "init":
        if not args.query or not args.songs:
            parser.error("init needs a Darunia folder and --songs DIR")
        _music_init(root, args.query, args.songs)
        return 0
    if args.action == "clear":
        _music_clear(root)
        return 0
    if args.action == "forget":
        _music_directory(root)
        if root.exists():
            with _music_lock(root):
                config = root / "config.json"
                if os.path.lexists(config):
                    _music_bytes(config)
                    config.unlink()
        print("Darunia link removed.")
        return 0
    config = _music_config(root)
    base = Path(config["songs"])
    if args.action == "list":
        if args.json:
            library = music_library(home)
            library["tracks"] = [track for track in library["tracks"] if args.query.casefold() in track["id"].casefold()]
            print(json.dumps(library, ensure_ascii=True, allow_nan=False))
            return 0
        for song in _music_songs(base):
            name = str(song.relative_to(base))
            if args.query.casefold() in name.casefold():
                print(_music_text(name))
        return 0
    query = args.query if args.action == "play" else args.action
    source = _music_select(base, query, menu)
    if source is None:
        return 0
    if not args.render_only:
        data = music_request({"action": "play", "ids": [str(source.relative_to(base))],
                              "index": 0, "seconds": args.seconds}, home)
        if args.json:
            print(json.dumps(data, ensure_ascii=True, allow_nan=False))
        else:
            print(data["message"] + " · " + _music_text(source.stem))
            print("Music continues in the background. godmode music stop ends the session.")
        return 0
    active = _music_animated() and not args.no_motion
    try:
        with _music_lock(root), _music_controls(sys.stdin.isatty() and sys.stdout.isatty(), terminal) as keyboard:
            path, details, cached = _music_render(root, config, source, args.seconds, active, keyboard, terminal[1])
            _music_print("  " + ("Cached" if cached else "Synthesized") + " · " + _music_clock(args.seconds))
            _music_print(str(path))
    except KeyboardInterrupt:
        print("\nMusic stopped.")
        return 130
    return 0


# --- godmode_music_player.py ---
"""Optional music session owner. Stdlib only; never imports credentials or core UI.

The private socket accepts semantic music commands, never arbitrary mpv commands.
mpv receives an inherited socketpair, so its unrestricted IPC has no named socket.
"""
import contextlib
import hashlib
import json
import math
import os
from pathlib import Path
import queue
import random
import select
import shutil
import signal
import socket
import stat
import subprocess
import sys
import threading
import time
import uuid
import wave


MUSIC_PROTOCOL_LIMIT = 1024 * 1024
MUSIC_QUEUE_LIMIT = 10000


def _music_stopped():
    return {"state": "stopped", "track": None, "queue": [], "index": -1,
            "position": 0.0, "duration": 0.0, "volume": 35.0,
            "repeat": "off", "shuffle": False, "levels": [], "message": "Stopped",
            "clock_source": "unavailable", "clock_age": None}


def _music_track(base, path):
    relative = str(path.relative_to(base))
    parent = str(path.relative_to(base).parent)
    return {"id": relative, "title": _music_text(path.stem),
            "collection": "Library" if parent == "." else _music_text(parent)}


def _music_saved(root):
    data = _music_stopped()
    try:
        saved = json.loads(_music_bytes(root / "session.json", MUSIC_PROTOCOL_LIMIT))
    except FileNotFoundError:
        return data, 180.0
    if not isinstance(saved, dict) or saved.get("version") != 1:
        raise ValueError("Invalid saved music session.")
    ids = saved.get("ids")
    if (not isinstance(ids, list) or len(ids) > MUSIC_QUEUE_LIMIT or any(
            not isinstance(item, str) or not item or len(item) > 4096 or Path(item).is_absolute()
            or ".." in Path(item).parts or Path(item).suffix.lower() != ".ootrs" for item in ids)):
        raise ValueError("Invalid saved music queue.")
    index = saved.get("index", -1)
    if isinstance(index, bool) or not isinstance(index, int) or not -1 <= index < max(1, len(ids)):
        raise ValueError("Invalid saved music index.")
    if not ids:
        index = -1
    data["queue"] = [_music_track(Path("."), Path(item)) for item in ids]
    data.update(index=index, track=data["queue"][index] if index >= 0 else None,
                volume=_music_number(saved.get("volume", 35), 0, 100, "Saved volume"))
    if saved.get("repeat") not in ("off", "all", "one") or not isinstance(saved.get("shuffle"), bool):
        raise ValueError("Invalid saved music playback modes.")
    data.update(repeat=saved["repeat"], shuffle=saved["shuffle"])
    seconds = _music_number(saved.get("seconds", 180), 1, 3600, "Saved render duration")
    return data, seconds


def music_library(home=None):
    result = {"configured": False, "tracks": [], "player_available": bool(shutil.which("mpv")),
              "no_motion": os.environ.get("GODMODE_NO_MOTION", "").lower() not in ("", "0", "false", "no")}
    try:
        config = _music_config(_music_root(home))
        base = Path(config["songs"])
        result.update(configured=True, backend=config["backend"], songs=config["songs"],
                      tracks=[_music_track(base, path) for path in _music_songs(base)])
    except (OSError, ValueError, TypeError) as error:
        result["error"] = _music_text(str(error))
    return result


def _music_session_path(root, create=False):
    _music_directory(root, create)
    directory = root / "session"
    _music_directory(directory, create)
    if directory.exists() and directory.stat().st_mode & 0o077:
        raise ValueError("Music session directory must be private (mode 0700).")
    path = directory / "control.sock"
    if len(os.fsencode(path)) >= 104:
        # Unix socket names are short on macOS. Hash only the already-validated
        # home, under an owned private directory; never trust a PID or /tmp link.
        base = Path("/tmp").resolve() / ("godmode-music-" + str(os.geteuid()))
        _music_directory(base, create)
        if base.exists() and base.stat().st_mode & 0o077:
            raise ValueError("Music runtime directory must be private (mode 0700).")
        directory = base / hashlib.sha256(os.fsencode(root)).hexdigest()[:24]
        _music_directory(directory, create)
        if directory.exists() and directory.stat().st_mode & 0o077:
            raise ValueError("Music runtime directory must be private (mode 0700).")
        path = directory / "control.sock"
    if os.path.lexists(path):
        info = path.lstat()
        if not stat.S_ISSOCK(info.st_mode) or info.st_uid != os.geteuid() or info.st_mode & 0o077:
            raise ValueError("Unsafe music session socket.")
    return path


def _music_json_line(connection):
    data = bytearray()
    while b"\n" not in data:
        block = connection.recv(min(65536, MUSIC_PROTOCOL_LIMIT + 1 - len(data)))
        if not block:
            raise ValueError("Incomplete music request.")
        data.extend(block)
        if len(data) > MUSIC_PROTOCOL_LIMIT:
            raise ValueError("Music request is too large.")
    line, rest = data.split(b"\n", 1)
    if rest.strip():
        raise ValueError("Send one command per music connection.")
    value = json.loads(line)
    if not isinstance(value, dict):
        raise ValueError("Music requests must be JSON objects.")
    return value


def _music_encode(value):
    data = (json.dumps(value, ensure_ascii=True, allow_nan=False, separators=(",", ":")) + "\n").encode()
    if len(data) > MUSIC_PROTOCOL_LIMIT:
        raise ValueError("Music response is too large; reduce the queue or library.")
    return data


def _music_contact(root, request):
    path = _music_session_path(root)
    if not path.exists():
        return None
    with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as client:
        client.settimeout(3)
        try:
            client.connect(str(path))
        except (FileNotFoundError, ConnectionRefusedError):
            return None
        client.sendall(_music_encode(request))
        response = _music_json_line(client)
    if response.get("ok") is not True:
        raise ValueError(response.get("error", "Music session rejected the command."))
    return response["data"]


def _music_launch(root):
    _music_session_path(root, True)
    executable = os.environ.get("GODMODE_EXECUTABLE")
    if executable:
        executable = os.path.abspath(executable)
        command = [executable]
    else:
        executable = os.path.abspath(sys.argv[0])
        if not Path(executable).is_file():
            raise ValueError("Cannot locate Godmode to start the music session.")
        command = [sys.executable, executable]
    env = _music_env()
    env["GODMODE_HOME"] = str(root.parent.parent)
    # The owner has no inherited terminal, credential environment or open pipes.
    child = subprocess.Popen(command + ["music", "__serve"], stdin=subprocess.DEVNULL,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             env=env, start_new_session=True, close_fds=True)
    # Keep/reap our direct child while this client lives. If the short-lived CLI
    # exits first, the detached owner is adopted by the operating system.
    threading.Thread(target=child.wait, daemon=True).start()
    deadline = time.monotonic() + 5
    while time.monotonic() < deadline:
        status = _music_contact(root, {"action": "status"})
        if status is not None:
            # Reap the losing process if a concurrent caller started the owner.
            if child.poll() is not None:
                child.wait()
            return
        if child.poll() is not None:
            # A concurrent owner may be between locking and binding.
            time.sleep(0.05)
        else:
            time.sleep(0.03)
    if child.poll() is None:
        _music_end(child)
    raise ValueError("Music session could not start. Check mpv and the music home permissions.")


def music_request(request, home=None):
    if not isinstance(request, dict) or not isinstance(request.get("action"), str):
        raise ValueError("Music request needs an action.")
    action = request["action"]
    fields = {"play": {"ids", "index", "seconds"}, "enqueue": {"ids"}, "seek": {"seconds"},
              "volume": {"value"}, "repeat": {"value"}, "shuffle": {"value"}, "remove": {"index"}}
    if set(request) - {"action"} - fields.get(action, set()):
        raise ValueError("Unknown field in music request.")
    _music_encode(request)  # Bound requests before opening/starting any process.
    if action in ("play", "enqueue"):
        ids = request.get("ids")
        if not isinstance(ids, list) or not ids or len(ids) > MUSIC_QUEUE_LIMIT or any(not isinstance(x, str) for x in ids):
            raise ValueError("Choose between 1 and 10,000 track IDs.")
    if action == "play":
        index = request.get("index", 0)
        if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < len(request["ids"]):
            raise ValueError("Invalid queue index.")
        _music_number(request.get("seconds", 180), 1, 3600, "Render duration")
    if action in ("seek", "volume"):
        _music_number(request.get("seconds" if action == "seek" else "value"),
                      -3600 if action == "seek" else 0, 3600 if action == "seek" else 100, action.title())
    if action == "repeat" and request.get("value") not in ("off", "one", "all"):
        raise ValueError("Repeat must be off, all, or one.")
    if action == "shuffle" and not isinstance(request.get("value"), bool):
        raise ValueError("Shuffle must be true or false.")
    if action == "library":
        return music_library(home)
    if action not in ("status", "play", "enqueue", "pause", "resume", "toggle", "next", "previous",
                      "seek", "volume", "repeat", "shuffle", "remove", "clear_queue", "stop"):
        raise ValueError("Unknown music action.")
    root = _music_root(home)
    result = _music_contact(root, request)
    if result is not None:
        return result
    if action in ("status", "stop", "clear_queue", "remove"):
        if action == "stop":
            try:
                return _music_saved(root)[0]
            except (OSError, ValueError, TypeError):
                return _music_stopped()
        data, seconds = _music_saved(root)
        if action == "remove":
            # Queue edits after Stop do not need a player, config, or daemon.
            if not root.exists():
                raise ValueError("Invalid queue index.")
            with _music_lock(root):
                session = _MusicSession(root)
                try:
                    return session.handle(request)
                finally:
                    session.close()
        if action == "clear_queue" and root.exists():
            with _music_lock(root):
                data.update(queue=[], index=-1, track=None)
                _music_save(root, data, seconds)
        return data
    if action not in ("play", "enqueue", "volume", "repeat", "shuffle"):
        raise ValueError("No music session is running. Choose a track first.")
    _music_config(root)  # Pin verification occurs before starting a session.
    if not shutil.which("mpv"):
        raise ValueError("Playback needs mpv. Install mpv, or use music play --render-only.")
    _music_launch(root)
    result = _music_contact(root, request)
    if result is None:
        raise ValueError("Music session exited before receiving the command.")
    return result


def music_session_bridge(home=None):
    """JSON lines until EOF. Disconnecting this client never stops playback."""
    while True:
        line = sys.stdin.buffer.readline(MUSIC_PROTOCOL_LIMIT + 1)
        if not line:
            return 0
        try:
            if len(line) > MUSIC_PROTOCOL_LIMIT or not line.endswith(b"\n"):
                raise ValueError("Music request is too large or incomplete.")
            result = {"ok": True, "data": music_request(json.loads(line), home)}
            encoded = _music_encode(result)
        except (OSError, ValueError, TypeError, KeyError) as error:
            result = {"ok": False, "error": _music_text(str(error))}
            encoded = _music_encode(result)
        try:
            sys.stdout.buffer.write(encoded)
            sys.stdout.buffer.flush()
        except (BrokenPipeError, OSError):
            return 0
        if len(line) > MUSIC_PROTOCOL_LIMIT:
            return 1


class _MusicMPV:
    """One process and one inherited local IPC connection; no exposed mpv socket."""
    def __init__(self, events, audio_output=None):
        executable = shutil.which("mpv")
        if not executable:
            raise ValueError("Playback needs mpv. Install mpv, or use music play --render-only.")
        self.events, self.pending = events, {}
        self.serial, self.closed = 0, False
        self.guard = threading.Lock()
        self.connection, inherited = socket.socketpair()
        command = [executable, "--no-config", "--idle=yes", "--terminal=no", "--vid=no",
                   "--audio-display=no", "--input-terminal=no", "--input-media-keys=no",
                   "--input-default-bindings=no", "--load-scripts=no", "--volume=35",
                   "--input-ipc-client=fd://" + str(inherited.fileno())]
        if audio_output:  # Explicit test construction only, never bridge-controlled.
            command.append("--ao=" + audio_output)
        try:
            self.child = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                          stderr=subprocess.DEVNULL, env=_music_env(), start_new_session=True,
                                          pass_fds=(inherited.fileno(),))
        except BaseException:
            self.connection.close()
            raise
        finally:
            inherited.close()
        self.reader = threading.Thread(target=self._read, daemon=True)
        self.reader.start()
        try:
            for number, name in enumerate(("audio-pts", "time-pos", "duration", "pause", "volume", "path"), 1):
                self.command("observe_property", number, name)
        except BaseException:
            self.close()
            raise

    def _read(self):
        try:
            with self.connection.makefile("rb") as stream:
                while True:
                    line = stream.readline(MUSIC_PROTOCOL_LIMIT + 1)
                    if not line or len(line) > MUSIC_PROTOCOL_LIMIT:
                        break
                    message = json.loads(line)
                    if "request_id" in message:
                        with self.guard:
                            waiting = self.pending.get(message["request_id"])
                        if waiting:
                            waiting.put(message)
                    elif message.get("event"):
                        self.events.put(message)
        except (OSError, ValueError):
            pass
        finally:
            self.events.put({"event": "transport-closed"})
            with self.guard:
                for waiting in self.pending.values():
                    waiting.put({"error": "connection closed"})

    def command(self, *command):
        waiting = queue.Queue()
        with self.guard:
            self.serial += 1
            serial = self.serial
            self.pending[serial] = waiting
        try:
            self.connection.sendall(_music_encode({"command": list(command), "request_id": serial}))
            try:
                reply = waiting.get(timeout=2)
            except queue.Empty:
                raise ValueError("mpv did not answer. Stop music and retry.") from None
            if reply.get("error") != "success":
                raise ValueError("mpv could not apply the playback command.")
            return reply.get("data")
        finally:
            with self.guard:
                self.pending.pop(serial, None)

    def close(self):
        if self.closed:
            return
        self.closed = True
        with contextlib.suppress(OSError):
            self.connection.shutdown(socket.SHUT_RDWR)
        self.connection.close()
        _music_end(self.child)
        self.reader.join(timeout=2)


def _music_number(value, low, high, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not low <= value <= high:
        raise ValueError(label + " is outside its allowed range.")
    return float(value)


def _music_save(root, data, seconds):
    saved = {"version": 1, "ids": [track["id"] for track in data["queue"]], "index": data["index"],
             "volume": data["volume"], "repeat": data["repeat"], "shuffle": data["shuffle"], "seconds": seconds}
    _music_atomic(root / "session.json", _music_encode(saved), MUSIC_PROTOCOL_LIMIT)


def _music_file_stamp(path):
    """Changes include inode/ctime, so restoring mtime cannot hide a replacement."""
    if not os.path.lexists(path):
        return (str(path), None)
    link = path.lstat()
    resolved = path.resolve()
    info = resolved.stat()
    if not stat.S_ISREG(info.st_mode):
        raise ValueError("Music preparation dependency is not a regular file.")
    return (str(path), link.st_dev, link.st_ino, link.st_ctime_ns, str(resolved),
            info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns, info.st_ctime_ns,
            info.st_mode, info.st_uid, info.st_nlink)


def _music_prepared_signature(config, source, details, verify=False):
    """Reuse only this known receipt policy; unknown adapters still render normally.

Verify every Darunia input against its receipt once, then compare full file
identity/change stamps on each reuse. Dynamic executable/ABI/font resolution is
repeated, including a previously missing font becoming available.
"""
    inputs = details.get("inputs")
    if not isinstance(inputs, dict) or inputs.get("policy") != "oot-or-whole-song-piano-v1":
        return None
    backend = Path(config["backend"])
    try:
        seq64 = backend / "tools/seq64/build/seq64_console"
        abi = None
        for parent in seq64.resolve().parents:
            if (parent / "abi").exists():
                abi = parent / "abi/4 - Zelda.xml"
                break
        ffmpeg = shutil.which("ffmpeg")
        if abi is None or not ffmpeg:
            return None
        files = [(source, inputs["source_sha256"]), (backend / "synthesize.py", inputs["adapter_sha256"]),
                 (backend / "oot-instruments.json", inputs["mapping_sha256"]),
                 (backend / "tools/florestan-subset.sf2", inputs["piano_soundfont_sha256"]),
                 (backend / "tools/render_synth", inputs["tools"]["renderer"]),
                 (seq64, inputs["tools"]["seq64"]), (Path(ffmpeg), inputs["tools"]["ffmpeg"]),
                 (abi, inputs["abi_sha256"])]
        instruments = inputs["instruments"]
        font = instruments.get("soundfont")
        if font:
            if not isinstance(font, str) or Path(font).is_absolute() or ".." in Path(font).parts:
                return None
            files.append((backend / "tools/oot-soundfonts" / font, instruments.get("soundfont_sha256")))
        signature = [config["backend"], config["songs"], config["sha256"]]
        for path, expected in files:
            before = _music_file_stamp(path)
            if verify:
                if expected is None:
                    if path.exists():
                        return None
                elif (not isinstance(expected, str) or len(expected) != 64
                      or _music_sha(path) != expected or before != _music_file_stamp(path)):
                    return None
            signature.append(before)
        return tuple(signature)
    except (OSError, KeyError, TypeError, ValueError):
        return None


class _MusicSession:
    def __init__(self, root, player_factory=_MusicMPV):
        self.root, self.player_factory = root, player_factory
        self.data, self.seconds = _music_saved(root)
        self.data["session_id"] = uuid.uuid4().hex
        self.events, self.rendered = queue.Queue(), queue.Queue()
        self.player = None
        self.worker, self.cancel = None, None
        self.generation = 0
        self.pending = None
        self.want_pause = False
        self.ending = False
        self.audio = None
        self.clock_at = None
        self.audio_clock_at = None
        self.started_at = None
        self.loaded_path = None
        self.history = []
        self.remaining = [i for i in range(len(self.data["queue"])) if i != self.data["index"]]
        random.shuffle(self.remaining)
        self.last_levels = 0
        self.awaiting_start = True
        self.entry_id = None
        self.closed = False
        self.prepared = {}
        self.prefetch_for = None

    def _resolve(self, ids):
        if not isinstance(ids, list) or not ids or len(ids) > MUSIC_QUEUE_LIMIT or any(not isinstance(x, str) for x in ids):
            raise ValueError("Choose between 1 and 10,000 track IDs.")
        config = _music_config(self.root)
        base = Path(config["songs"])
        library = {str(path.relative_to(base)): _music_track(base, path) for path in _music_songs(base)}
        if any(item not in library for item in ids):
            raise ValueError("A track is missing from the local library. Refresh the library.")
        return [dict(library[item]) for item in ids]

    def _cancel_work(self):
        self.generation += 1
        self.pending = None
        self.prefetch_for = None
        if self.cancel:
            self.cancel.set()
        if self.audio:
            self.audio.close()
            self.audio = None
        self.loaded_path = None
        if self.player:
            try:
                self.player.command("stop")
            except (OSError, ValueError):
                self.player.close()
                self.player = None
        while True:
            try:
                self.events.get_nowait()
            except queue.Empty:
                break
        self.awaiting_start, self.entry_id = True, None
        self.clock_at = self.audio_clock_at = None
        self.data.update(position=0.0, duration=0.0, levels=[], clock_source="unavailable", clock_age=None)

    def _start(self, index, remember=True, paused=False):
        if not 0 <= index < len(self.data["queue"]):
            return
        # Saved queue entries may have moved since the previous session.
        self._resolve([self.data["queue"][index]["id"]])
        previous = self.data["index"]
        if remember and previous >= 0 and previous != index:
            self.history.append(previous)
        self._cancel_work()
        self.data.update(index=index, track=self.data["queue"][index], state="preparing", message="Preparing audio")
        self.want_pause = paused
        self.started_at = time.monotonic()
        self.pending = (self.generation, dict(self.data["track"]), self.seconds, "play")
        self.remaining = [value for value in self.remaining if value != index]

    def _begin_render(self):
        if self.worker is not None or self.pending is None:
            return
        generation, track, seconds, purpose = self.pending
        self.pending = None
        cancel = self.cancel = threading.Event()
        remembered = self.prepared.get((track["id"], seconds))
        def render():
            try:
                config = _music_config(self.root)
                source = Path(config["songs"]) / track["id"]
                _music_directory(source.parent)
                _music_bytes(source, 700 * 1024 * 1024)
                value, signature = None, None
                if remembered:
                    old_value, old_signature, wav_stamp = remembered
                    current = _music_prepared_signature(config, source, old_value[1])
                    _music_validate_cache(self.root / "cache")
                    if current is not None and current == old_signature and _music_file_stamp(old_value[0]) == wav_stamp:
                        value, signature = old_value, current
                if value is None:
                    value = _music_render(self.root, config, source, seconds, cancel=cancel, quiet=True)
                    signature = _music_prepared_signature(config, source, value[1], verify=True)
                self.rendered.put((generation, purpose, track["id"], seconds, value, signature, None))
            except (Exception, KeyboardInterrupt) as error:
                self.rendered.put((generation, purpose, track["id"], seconds, None, None, error))
        self.worker = threading.Thread(target=render, daemon=True)
        self.worker.start()

    def _finish_render(self):
        try:
            generation, purpose, track_id, seconds, value, signature, error = self.rendered.get_nowait()
        except queue.Empty:
            return
        self.worker.join(timeout=0.1)
        self.worker = None
        if generation != self.generation:
            return
        if error is not None:
            if purpose == "play":
                self.data.update(state="error", message=_music_text(str(error)) or "Audio preparation failed")
            return
        if signature is not None:
            key = (track_id, seconds)
            self.prepared.pop(key, None)
            self.prepared[key] = (value, signature, _music_file_stamp(value[0]))
            while len(self.prepared) > 4:
                del self.prepared[next(iter(self.prepared))]
        if purpose == "prefetch":
            return
        path, details, cached = value
        try:
            audio = wave.open(str(path), "rb")
            if audio.getsampwidth() != 2 or audio.getnchannels() not in (1, 2) or audio.getcomptype() != "NONE":
                audio.close()
                raise ValueError("Music playback needs 16-bit PCM WAV audio.")
            self.audio = audio
            self.data["duration"] = audio.getnframes() / audio.getframerate()
            if self.player is None:
                self.player = self.player_factory(self.events)
            self.player.command("set_property", "volume", self.data["volume"])
            self.player.command("set_property", "pause", self.want_pause)
            self.loaded_path = str(path)
            self.player.command("loadfile", self.loaded_path, "replace")
            self.data["message"] = "Starting audio"
        except (OSError, ValueError, wave.Error) as failure:
            self.data.update(state="error", message=_music_text(str(failure)))

    def _next(self, natural=False):
        count, current = len(self.data["queue"]), self.data["index"]
        if not count:
            return
        if natural and self.data["repeat"] == "one":
            self._start(current, remember=False)
            return
        if self.data["shuffle"]:
            if not self.remaining and (not natural or self.data["repeat"] == "all"):
                self.remaining = [i for i in range(count) if i != current]
                random.shuffle(self.remaining)
                if not self.remaining and self.data["repeat"] == "all":
                    self.remaining = [current]
            target = self.remaining.pop() if self.remaining else None
        else:
            target = current + 1
            if target >= count:
                target = 0 if self.data["repeat"] == "all" else None
        if target is None:
            self._cancel_work()
            self.data.update(state="stopped", message="Queue finished")
        else:
            self._start(target)
        _music_save(self.root, self.data, self.seconds)

    def _process_event(self, event):
        kind = event.get("event")
        if kind == "transport-closed":
            if not self.ending:
                self.data.update(state="error", message="Audio player exited. Choose a track to retry.", levels=[])
                if self.player:
                    self.player.close()
                    self.player = None
            return
        if kind == "start-file" and self.loaded_path:
            self.awaiting_start = False
            self.entry_id = event.get("playlist_entry_id")
            return
        if kind == "end-file":
            if self.entry_id is not None and event.get("playlist_entry_id") != self.entry_id:
                return
            if event.get("reason") == "eof" and self.loaded_path and not self.awaiting_start and self.data["state"] in ("playing", "paused"):
                self._next(natural=True)
            elif event.get("reason") == "error" and self.loaded_path:
                self.data.update(state="error", message="mpv could not play the rendered audio.", levels=[])
            return
        if kind != "property-change" or not self.loaded_path or self.awaiting_start:
            return
        name, value = event.get("name"), event.get("data")
        if name in ("audio-pts", "time-pos") and isinstance(value, (int, float)) and math.isfinite(value):
            now = time.monotonic()
            if name == "audio-pts":
                self.audio_clock_at = now
            elif self.audio_clock_at is not None and now - self.audio_clock_at < 0.5:
                return
            self.clock_at = now
            self.data.update(position=max(0.0, min(float(value), self.data["duration"])),
                             clock_source="mpv:" + name, state="paused" if self.want_pause else "playing",
                             message="Paused" if self.want_pause else "Playing")
        elif name == "duration" and isinstance(value, (int, float)) and math.isfinite(value):
            self.data["duration"] = max(0.0, float(value))
        elif name == "pause" and isinstance(value, bool):
            self.want_pause = value
            if self.data["state"] in ("playing", "paused"):
                self.data.update(state="paused" if value else "playing", message="Paused" if value else "Playing")

    def tick(self):
        self._finish_render()
        while True:
            try:
                self._process_event(self.events.get_nowait())
            except queue.Empty:
                break
            except (OSError, ValueError, TypeError) as error:
                self.data.update(state="error", message=_music_text(str(error)), levels=[])
        self._begin_render()
        if (self.worker is None and self.pending is None and self.data["state"] == "playing"
                and self.data["queue"]):
            current, count = self.data["index"], len(self.data["queue"])
            if self.data["repeat"] == "one":
                target = current
            elif self.data["shuffle"]:
                target = self.remaining[-1] if self.remaining else None
            else:
                target = current + 1 if current + 1 < count else (0 if self.data["repeat"] == "all" else None)
            if target is not None:
                track = self.data["queue"][target]
                key = (self.generation, track["id"], self.seconds)
                if self.prefetch_for != key and (track["id"], self.seconds) not in self.prepared:
                    self.prefetch_for = key
                    self.pending = (self.generation, dict(track), self.seconds, "prefetch")
                    self._begin_render()

    def snapshot(self):
        now = time.monotonic()
        self.data["clock_age"] = None if self.clock_at is None else max(0.0, now - self.clock_at)
        if self.data["state"] == "preparing" and self.started_at is not None:
            self.data["message"] = ("Starting audio" if self.loaded_path else "Preparing audio") + " · " + str(int(now - self.started_at)) + "s"
        if self.data["state"] == "playing" and self.clock_at is not None and now - self.clock_at > 2:
            self.data["message"] = "Waiting for audio clock"
            self.data["levels"] = []
        elif self.audio and self.data["state"] == "playing" and now - self.last_levels >= 0.08:
            try:
                self.data["levels"] = _music_levels(self.audio, self.data["position"])
                self.last_levels = now
            except (OSError, ValueError, wave.Error):
                self.data["levels"] = []
        elif self.data["state"] != "playing":
            self.data["levels"] = []
        # Serialize to copy nested queue objects before the next mutation.
        return json.loads(json.dumps(self.data))

    def handle(self, request):
        action = request.get("action")
        if action == "status":
            return self.snapshot()
        if action == "play":
            tracks = self._resolve(request.get("ids"))
            _music_encode({"queue": tracks, "reserved": " " * 4096})
            index = request.get("index", 0)
            if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < len(tracks):
                raise ValueError("Invalid queue index.")
            seconds = _music_number(request.get("seconds", 180), 1, 3600, "Render duration")
            self.data["queue"], self.seconds = tracks, seconds
            self.data["index"] = -1
            self.history = []
            self.remaining = list(range(len(tracks)))
            random.shuffle(self.remaining)
            self._start(index)
        elif action == "enqueue":
            tracks = self._resolve(request.get("ids"))
            old = len(self.data["queue"])
            if old + len(tracks) > MUSIC_QUEUE_LIMIT:
                raise ValueError("The queue can hold at most 10,000 tracks.")
            _music_encode({"queue": self.data["queue"] + tracks, "reserved": " " * 4096})
            self.data["queue"].extend(tracks)
            self.remaining.extend(range(old, old + len(tracks)))
            random.shuffle(self.remaining)
        elif action in ("pause", "resume", "toggle"):
            if self.data["state"] not in ("playing", "paused", "preparing"):
                raise ValueError("Choose a track to play first.")
            self.want_pause = not self.want_pause if action == "toggle" else action == "pause"
            if self.player and self.loaded_path:
                self.player.command("set_property", "pause", self.want_pause)
            if self.data["state"] != "preparing":
                self.data.update(state="paused" if self.want_pause else "playing", message="Paused" if self.want_pause else "Playing")
        elif action == "next":
            self._next()
        elif action == "previous":
            target = self.history.pop() if self.history else max(0, self.data["index"] - 1)
            self._start(target, remember=False)
        elif action == "seek":
            offset = _music_number(request.get("seconds"), -3600, 3600, "Seek offset")
            if not self.player or not self.loaded_path or self.data["state"] not in ("playing", "paused"):
                raise ValueError("Audio must be ready before seeking.")
            target = max(0.0, min(self.data["duration"], self.data["position"] + offset))
            self.player.command("seek", target, "absolute+exact")
            self.data.update(levels=[], message="Seeking")
            self.audio_clock_at = None
            self.clock_at = None
        elif action == "volume":
            value = _music_number(request.get("value"), 0, 100, "Volume")
            if self.player:
                self.player.command("set_property", "volume", value)
            self.data["volume"] = value
        elif action == "repeat":
            value = request.get("value")
            if value not in ("off", "all", "one"):
                raise ValueError("Repeat must be off, all, or one.")
            self.data["repeat"] = value
        elif action == "shuffle":
            value = request.get("value")
            if not isinstance(value, bool):
                raise ValueError("Shuffle must be true or false.")
            self.data["shuffle"] = value
            self.remaining = [i for i in range(len(self.data["queue"])) if i != self.data["index"]]
            random.shuffle(self.remaining)
        elif action == "remove":
            index = request.get("index")
            if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < len(self.data["queue"]):
                raise ValueError("Invalid queue index.")
            current = self.data["index"]
            previous_state = self.data["state"]
            preserve_pause = previous_state == "paused" or (previous_state == "preparing" and self.want_pause)
            self.data["queue"].pop(index)
            self.history = [i - (i > index) for i in self.history if i != index]
            self.remaining = [i - (i > index) for i in self.remaining if i != index]
            if index == current:
                if self.data["queue"]:
                    replacement = min(index, len(self.data["queue"]) - 1)
                    if previous_state in ("playing", "paused", "preparing"):
                        self._start(replacement, remember=False, paused=preserve_pause)
                    else:
                        self._cancel_work()
                        self.data.update(index=replacement, track=self.data["queue"][replacement],
                                         state="stopped", message="Stopped")
                else:
                    self._cancel_work()
                    self.data.update(index=-1, track=None, state="stopped", message="Queue empty")
            elif index < current:
                self.data["index"] -= 1
        elif action in ("clear_queue", "stop"):
            self._cancel_work()
            self.data.update(state="stopped", message="Stopped")
            if action == "clear_queue":
                self.data.update(queue=[], index=-1, track=None)
            self.history, self.remaining = [], []
            if action == "stop":
                self.ending = True
        else:
            raise ValueError("Unknown music action.")
        _music_save(self.root, self.data, self.seconds)
        return self.snapshot()

    def close(self):
        if self.closed:
            return
        self.closed = True
        self.ending = True
        if self.cancel:
            self.cancel.set()
        if self.worker:
            self.worker.join(timeout=4)
        if self.audio:
            self.audio.close()
        if self.player:
            self.player.close()


def music_session_serve(home=None):
    root = _music_root(home)
    os.umask(0o077)
    path = _music_session_path(root, True)
    # The existing music lock also guards clear/init/forget and simultaneous starts.
    try:
        with _music_lock(root):
            if path.exists():
                path.unlink()  # Safe owner-only socket; the lifetime lock proves no live owner.
            session = _MusicSession(root)
            with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as server:
                server.bind(str(path))
                os.chmod(path, 0o600)
                server.listen(8)
                server.settimeout(0.05)
                def finish(signum, frame):
                    session.ending = True
                previous = {signum: signal.signal(signum, finish) for signum in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP)}
                try:
                    while not session.ending:
                        session.tick()
                        try:
                            client, _ = server.accept()
                        except socket.timeout:
                            continue
                        with client:
                            client.settimeout(0.5)
                            try:
                                request = _music_json_line(client)
                                result = {"ok": True, "data": session.handle(request)}
                                if session.ending:
                                    session.close()
                                    with contextlib.suppress(FileNotFoundError):
                                        path.unlink()
                            except (OSError, ValueError, TypeError, KeyError) as error:
                                result = {"ok": False, "error": _music_text(str(error))}
                            try:
                                encoded = _music_encode(result)
                            except (ValueError, TypeError):
                                encoded = _music_encode({"ok": False, "error": "Music response exceeds the protocol limit."})
                            with contextlib.suppress(OSError):
                                client.sendall(encoded)
                finally:
                    session.close()
                    with contextlib.suppress(FileNotFoundError):
                        path.unlink()
                    for signum, handler in previous.items():
                        signal.signal(signum, handler)
    except ValueError as error:
        if "Music is running" not in str(error):
            raise
        # Another launch won the same per-home lifetime lock.
    return 0


